double h = (b - a) / 2;
double x = (a + b) / 2;
double fa = f(a);
double fb = f(b);
double fx = f(x);
double I1 = h * fa;
double I2 = h * fb;
double I3 = h * fx;
double error = std::abs(I3 - (I1 + I2) / 2);
if (error < precision) {
    return I3;
} else {
    double result1 = numerical::adaptive_midpoint(f, a, x, precision);
    double result2 = numerical::adaptive_midpoint(f, x, b, precision);
    return result1 + result2;
}

